def describe_hyper_scale_intelligence() -> str:
    lines = [
        "TitanAI Hyper-Scale Intelligence Architecture Era",
        "",
        "This layer frames TitanAI as a distributed intelligence operating architecture spanning reasoning, infrastructure, software evolution, agents, enterprises, research, learning, commerce, personal intelligence, creation, observability, communication, governance, and a universal intelligence operating system.",
        "",
    ]
    for capability in HYPERSCALE_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
